def _err(code: int, msg: str) -> Any: raise HTTPException(status_code=code, detail=msg)

def _unpack_row(r: sqlite3.Row) -> Dict[str, Any]: d = dict(r); d["segment_tags"] = json.loads(d.pop("segment_tags_json", "[]") or "[]"); d["recent_posts"] = json.loads(d.pop("recent_posts_json", "[]") or "[]"); d["fit_reasons"] = json.loads(d.pop("fit_reasons_json", "[]") or "[]"); d["score_breakdown"] = json.loads(d.pop("score_breakdown_json", "{}") or "{}"); d["grounding_check"] = json.loads(d.pop("grounding_check_json", "{}") or "{}"); d["is_test_account"] = bool(d["is_test_account"]); return d

@app.on_event("startup")
def on_startup() -> None: init_db()

