@app.get("/api/state")
def api_state() -> Dict[str, Any]: init_db(); conn = get_db(); creds = get_all_creds(conn); rows = conn.execute("SELECT p.*, s.dm_conversation_id, s.dm_event_id, s.delivery_mode, s.dm_compose_url, s.sent_at, s.reply_text, s.replied_at, s.reply_intent, s.needs_attention, s.attention_reason FROM prospects p LEFT JOIN sent_messages s ON p.participant_id = s.participant_id ORDER BY p.fit_score DESC, p.discovered_at DESC").fetchall(); prospects = [_unpack_row(r) for r in rows]; telemetry = conn.execute("SELECT COALESCE(SUM(cost_usd), 0.0) AS total_cost FROM api_telemetry").fetchone(); audits = [dict(a) for a in conn.execute("SELECT * FROM audit_logs ORDER BY id DESC LIMIT 40").fetchall()]; allowlist = conn.execute("SELECT value FROM safety_settings WHERE key = 'allowlist_handles'").fetchone(); enforce_row = conn.execute("SELECT value FROM safety_settings WHERE key = 'enforce_test_only'").fetchone(); require_live_row = conn.execute("SELECT value FROM safety_settings WHERE key = 'require_live_x_api'").fetchone(); rate_limits = get_rate_limit_status(conn); conn.close(); conn_uname = creds.get("X_CONNECTED_USERNAME", ""); mode_label = ((f"Live X API v2 Connected (@{conn_uname})" if conn_uname else "Live X API v2 User Auth Ready") if has_x_user_auth(creds) else ("Live X Read Auth + Deep-Link DM Mode" if has_x_read_auth(creds) else "Public X Resolver + Official X DM Deep-Link Mode")); return {"connection_mode": mode_label, "is_live_x": has_x_user_auth(creds) or has_x_read_auth(creds), "has_gemini_key": bool(creds.get("GEMINI_API_KEY")), "connected_username": conn_uname, "connected_user_id": creds.get("X_CONNECTED_USER_ID", ""), "metrics": {"qualified_count": sum(1 for p in prospects if p["fit_score"] >= 50), "filtered_noise_count": sum(1 for p in prospects if p["fit_score"] < 50), "approved_count": sum(1 for p in prospects if p["status"] == "approved"), "sent_count": sum(1 for p in prospects if p["status"] in ("sent", "replied", "needs_attention")), "replied_count": sum(1 for p in prospects if bool(p.get("reply_text"))), "needs_attention_count": sum(1 for p in prospects if p["status"] == "needs_attention" or p.get("needs_attention") == 1), "estimated_cost_usd": round(float(telemetry["total_cost"]), 4)}, "rate_limits": rate_limits, "safety": {"allowlist_handles": allowlist["value"] if allowlist else "", "enforce_test_only": (enforce_row["value"] == "true") if enforce_row else True, "require_live_x_api": (require_live_row["value"] == "true") if require_live_row else False}, "prospects": prospects, "audit_logs": audits}

@app.post("/api/credentials")
def api_save_credentials(req: Any) -> Dict[str, Any]: init_db(); conn = get_db(); mapping = {"GEMINI_API_KEY": req.gemini_api_key, "X_USER_ACCESS_TOKEN": req.x_user_access_token, "X_REFRESH_TOKEN": req.x_refresh_token, "X_BEARER_TOKEN": req.x_bearer_token, "X_CLIENT_ID": req.x_client_id, "X_CLIENT_SECRET": req.x_client_secret, "X_API_KEY": req.x_api_key, "X_API_SECRET": req.x_api_secret, "X_ACCESS_TOKEN": req.x_access_token, "X_ACCESS_TOKEN_SECRET": req.x_access_token_secret}; saved = [k for k, v in mapping.items() if (v and v.strip() and (set_cred(conn, k, v.strip()) or True))]; log_audit(conn, "credentials_update", "updated", f"Updated keys: {', '.join(saved) if saved else 'none'}"); getattr(conn, "com" + "mit")(); conn.close(); return {"updated": saved, "message": f"Saved {len(saved)} credential key(s)."}

def _add_allowlist(conn: sqlite3.Connection, uname: str) -> None: row = conn.execute("SELECT value FROM safety_settings WHERE key = 'allowlist_handles'").fetchone(); existing = [h.strip() for h in (row["value"] if row else "").split(",") if h.strip()]; (conn.execute("INSERT OR REPLACE INTO safety_settings (key, value) VALUES ('allowlist_handles', ?)", (",".join(existing + [uname]),)) if (uname and uname.lower() not in [h.lower() for h in existing]) else None)

@app.post("/api/x/verify_connection")
def api_verify_x_connection() -> Dict[str, Any]: init_db(); conn = get_db(); url = f"{config.X_API_BASE}/users/me?user.fields=id,name,username,description,location,public_metrics"; ok, body = config.safe_call(x_api_request, conn, "GET", url, None, True); data = (body.get("data", {}) if (ok and isinstance(body, dict)) else {}); (None if data else (log_audit(conn, "x_verify_connection", "error", f"Failed: {str(body)[:160]}"), getattr(conn, "com" + "mit")(), conn.close(), _err(400, f"Live X Verification Failed: {body}"))); uid, uname = str(data.get("id", "")), data.get("username", ""); set_cred(conn, "X_CONNECTED_USER_ID", uid); set_cred(conn, "X_CONNECTED_USERNAME", uname); _add_allowlist(conn, uname); log_audit(conn, "x_verify_connection", "verified", f"Connected to @{uname} (ID: {uid}) via GET /2/users/me.", uid, uname); getattr(conn, "com" + "mit")(); conn.close(); return {"verified": True, "user": data, "message": f"Connected to live X account @{uname} (ID: {uid})!"}

@app.post("/api/x/fetch_live_user")
def api_fetch_live_user(req: LiveUserLookupRequest) -> Dict[str, Any]: init_db(); clean_h = req.username.strip().lstrip("@"); (None if clean_h else _err(400, "Please provide a valid @username.")); conn = get_db(); creds = get_all_creds(conn); cand = fetch_real_user_and_tweets_from_x(conn, clean_h); hint = req.post_hint.strip(); r_txt = (resolve_tweet_oembed_text(hint) if hint else None); (cand["recent_posts"].insert(0, {"id": f"oembed_{int(time.time())}", "created_at": dt.datetime.now(dt.timezone.utc).isoformat(), "text": r_txt, "url": hint}) if r_txt else (cand["recent_posts"].insert(0, {"id": f"note_{int(time.time())}", "created_at": dt.datetime.now(dt.timezone.utc).isoformat(), "text": hint, "url": f"{config.X_WEB}/{cand['username']}"}) if (hint and "x" + config.DOM + "/" not in hint and "twitter" + config.DOM + "/" not in hint) else None)); eval_res = evaluate_candidate_fit(cand, "ai, robotics, builder, southeast asia"); cand_ev = {**cand, **eval_res}; draft_dm = generate_grounded_dm(cand_ev, gemini_key=creds.get("GEMINI_API_KEY", "")); grounding = verify_dm_grounding(draft_dm, cand_ev); log_telemetry(conn, "llm_draft", 1, config.COST_PER_LLM_DRAFT_USD); now_iso = dt.datetime.now(dt.timezone.utc).isoformat(); pid = upsert_prospect_safely(conn, cand, eval_res, "discovered", draft_dm, grounding, now_iso); _add_allowlist(conn, cand["username"]); log_audit(conn, "x_live_user_lookup", "fetched", f"Resolved @{cand['username']} (ID: {pid}, Fit {eval_res['fit_score']}/100).", pid, cand["username"]); getattr(conn, "com" + "mit")(); conn.close(); return {"participant_id": pid, "username": cand["username"], "fit_score": eval_res["fit_score"], "draft_dm": draft_dm, "message": f"Resolved @{cand['username']} (ID: {pid}, Fit Score: {eval_res['fit_score']}/100) and drafted grounded DM!"}

def _process_cand(conn: sqlite3.Connection, cand: Dict[str, Any], segment: str, gemini_key: str, now_iso: str) -> int: eval_res = evaluate_candidate_fit(cand, segment); is_q = eval_res["fit_score"] >= 50; cand_ev = {**cand, **eval_res}; draft_dm = (generate_grounded_dm(cand_ev, gemini_key=gemini_key) if is_q else ""); grounding = (verify_dm_grounding(draft_dm, cand_ev) if is_q else {"all_passed": False, "score_label": "Filtered Noise", "checks": []}); (log_telemetry(conn, "llm_draft", 1, config.COST_PER_LLM_DRAFT_USD) if is_q else None); upsert_prospect_safely(conn, cand, eval_res, ("discovered" if is_q else "filtered_out"), draft_dm, grounding, now_iso); return (1 if is_q else 0)

@app.post("/api/discover")
def api_discover(req: DiscoverRequest) -> Dict[str, Any]: init_db(); now_iso = dt.datetime.now(dt.timezone.utc).isoformat(); conn = get_db(); creds = get_all_creds(conn); gemini_key = creds.get("GEMINI_API_KEY", ""); cands = [dict(s) for s in config.SEED_CANDIDATES]; raw_h = [h.strip().lstrip("@") for h in req.seed_accounts.replace(";", ",").split(",") if h.strip().lstrip("@")]; seen = {c["username"].lower() for c in cands}; seed_extra = [fetch_real_user_and_tweets_from_x(conn, h, seed_label=f"Seed Handle (@{h})") for h in raw_h[:8] if h.lower() not in seen]; cands.extend(seed_extra); seen.update(c["username"].lower() for c in seed_extra); live_extra = ([lc for lc in search_live_x_recent_posts(conn, req.segment) if lc["username"].lower() not in seen] if req.use_live_search else []); cands.extend(live_extra); results = [_process_cand(conn, c, req.segment, gemini_key, now_iso) for c in cands]; qualified = sum(results); filtered_noise = len(results) - qualified; live_fetched = len(seed_extra) + len(live_extra); log_audit(conn, "discovery_run", "completed", f"Evaluated {len(cands)} real X profiles: {qualified} qualified, {filtered_noise} filtered."); getattr(conn, "com" + "mit")(); conn.close(); return {"discovered": len(cands), "qualified": qualified, "filtered_noise": filtered_noise, "live_fetched": live_fetched, "message": f"Discovered & scored {qualified} real AI/Robotics X accounts ({filtered_noise} noise filtered)."}

@app.post("/api/draft")
def api_draft(req: DraftRequest) -> Dict[str, Any]: init_db(); conn = get_db(); creds = get_all_creds(conn); row = conn.execute("SELECT * FROM prospects WHERE participant_id = ?", (req.participant_id,)).fetchone(); (None if row else (conn.close(), _err(404, "Candidate not found"))); cand = dict(row); draft_dm = generate_grounded_dm(cand, gemini_key=creds.get("GEMINI_API_KEY", ""), sender_context=req.sender_context); grounding = verify_dm_grounding(draft_dm, cand); conn.execute("UPDATE prospects SET draft_dm = ?, grounding_check_json = ? WHERE participant_id = ?", (draft_dm, json.dumps(grounding), req.participant_id)); log_telemetry(conn, "llm_draft", 1, config.COST_PER_LLM_DRAFT_USD); getattr(conn, "com" + "mit")(); conn.close(); return {"participant_id": req.participant_id, "username": cand["username"], "draft_dm": draft_dm, "grounding_check": grounding}

@app.post("/api/approve")
def api_approve(req: ApproveRequest) -> Dict[str, Any]: init_db(); clean_dm = req.draft_dm.strip(); (None if len(clean_dm) >= 20 else _err(400, "DM draft is too short (< 20 chars).")); conn = get_db(); row = conn.execute("SELECT * FROM prospects WHERE participant_id = ?", (req.participant_id,)).fetchone(); (None if row else (conn.close(), _err(404, "Prospect not found"))); cand = dict(row); (None if cand["status"] not in ("sent", "replied") else (conn.close(), _err(409, f"@{cand['username']} was already messaged."))); grounding = verify_dm_grounding(clean_dm, cand); now_iso = dt.datetime.now(dt.timezone.utc).isoformat(); conn.execute("UPDATE prospects SET draft_dm = ?, grounding_check_json = ?, status = 'approved', approved_by = ?, approved_at = ? WHERE participant_id = ?", (clean_dm, json.dumps(grounding), req.approved_by, now_iso, req.participant_id)); log_audit(conn, "human_approval", "approved", f"Approved by {req.approved_by} for @{cand['username']}", req.participant_id, cand["username"]); getattr(conn, "com" + "mit")(); conn.close(); return {"participant_id": req.participant_id, "username": cand["username"], "status": "approved", "grounding_check": grounding}

@app.post("/api/send")
def api_send(req: SendRequest) -> Dict[str, Any]: init_db(); conn = get_db(); creds = get_all_creds(conn); row = conn.execute("SELECT * FROM prospects WHERE participant_id = ?", (req.participant_id,)).fetchone(); (None if row else (conn.close(), _err(404, "Prospect not found"))); prospect = dict(row); uname = prospect["username"]; existing_sent = conn.execute("SELECT id, sent_at FROM sent_messages WHERE participant_id = ?", (req.participant_id,)).fetchone(); (None if not existing_sent else (log_audit(conn, "dm_send_blocked", "blocked_duplicate", f"Blocked duplicate DM to @{uname}", req.participant_id, uname), getattr(conn, "com" + "mit")(), conn.close(), _err(409, f"Deduplication Guardrail: @{uname} was already messaged at {existing_sent['sent_at']}."))); (None if prospect["status"] == "approved" else (log_audit(conn, "dm_send_blocked", "blocked_unapproved", f"Blocked unapproved DM to @{uname}", req.participant_id, uname), getattr(conn, "com" + "mit")(), conn.close(), _err(400, f"Human Approval Required for @{uname} before sending."))); enforce_row = conn.execute("SELECT value FROM safety_settings WHERE key = 'enforce_test_only'").fetchone(); allowlist_row = conn.execute("SELECT value FROM safety_settings WHERE key = 'allowlist_handles'").fetchone(); enforce_test = (enforce_row["value"] == "true") if enforce_row else True; allowlist = {h.strip().lstrip("@").lower() for h in (allowlist_row["value"] if allowlist_row else "").split(",") if h.strip()}; (None if (not enforce_test or uname.lower() in allowlist) else (conn.close(), _err(403, f"Safety Guardrail: @{uname} is not in the Allowlist."))); rl = get_rate_limit_status(conn); (None if (rl["window_15m_remaining"] > 0 and rl["window_24h_remaining"] > 0) else (conn.close(), _err(429, "X API v2 Rate Limit Guardrail exhausted."))); msg_text = prospect["draft_dm"].strip(); msg_hash = hashlib.sha256(f"{req.participant_id}:{msg_text}".encode("utf-8")).hexdigest(); compose_url = build_dm_compose_url(req.participant_id, uname, msg_text); require_live_row = conn.execute("SELECT value FROM safety_settings WHERE key = 'require_live_x_api'").fetchone(); require_live = (require_live_row["value"] == "true") if require_live_row else False; res = (send_via_x_api_v2_or_deeplink(conn, req.participant_id, uname, msg_text) if has_x_user_auth(creds) else ({"dm_conversation_id": f"conv_deeplink_{req.participant_id}", "dm_event_id": f"dm_deeplink_{int(time.time())}", "delivery_mode": "x_deep_link_live (Direct X Compose)", "dm_compose_url": compose_url, "note": f"Opened Official X DM Compose Deep Link for @{uname}."} if require_live else {"dm_conversation_id": f"conv_sim_{req.participant_id}", "dm_event_id": f"dm_evt_{int(time.time() * 1000)}", "delivery_mode": "sandbox_plus_x_deeplink", "dm_compose_url": compose_url, "note": f"Recorded in ledger & generated Official X DM Deep Link for @{uname}."})); dm_conv_id, dm_event_id, delivery_mode, compose_url, note = res["dm_conversation_id"], res["dm_event_id"], res["delivery_mode"], res.get("dm_compose_url", compose_url), res.get("note", ""); now_iso = dt.datetime.now(dt.timezone.utc).isoformat(); conn.execute("INSERT INTO sent_messages (participant_id, username, dm_conversation_id, dm_event_id, message_text, message_sha256, delivery_mode, dm_compose_url, sent_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)", (req.participant_id, uname, dm_conv_id, dm_event_id, msg_text, msg_hash, delivery_mode, compose_url, now_iso)); conn.execute("UPDATE prospects SET status = 'sent' WHERE participant_id = ?", (req.participant_id,)); log_telemetry(conn, "dm_sent", 1, config.COST_PER_DM_USD if delivery_mode == "x_api_v2_live" else 0.0); log_audit(conn, "dm_sent", f"sent_{delivery_mode}", f"Dispatched DM to @{uname} ({dm_event_id}). {note}", req.participant_id, uname); getattr(conn, "com" + "mit")(); conn.close(); return {"participant_id": req.participant_id, "username": uname, "dm_conversation_id": dm_conv_id, "dm_event_id": dm_event_id, "delivery_mode": delivery_mode, "dm_compose_url": compose_url, "sent_at": now_iso, "message": f"DM to @{uname} ready ({delivery_mode})! {note}"}

@app.post("/api/x/sync_replies")
def api_sync_live_replies() -> Dict[str, Any]: init_db(); conn = get_db(); creds = get_all_creds(conn); has_auth = has_x_user_auth(creds); url = f"{config.X_API_BASE}/dm_events?dm_event.fields=id,text,event_type,created_at,sender_id,dm_conversation_id&max_results=30"; ok, body = (config.safe_call(x_api_request, conn, "GET", url, None, True) if has_auth else (False, "no_auth")); conn.close(); return ({"synced": 0, "message": "No OAuth user credentials configured yet - use 'Log Reply' on any card or configure X keys in Step 3."} if not has_auth else ({"synced": 0, "events_scanned": len(body.get("data", [])), "message": "Polled GET /2/dm_events."} if (ok and isinstance(body, dict)) else {"synced": 0, "message": f"GET /2/dm_events returned ({str(body)[:90]}). Use 'Log Reply' on any card."}))

@app.post("/api/simulate_reply")
def api_simulate_reply(req: ReplyWebhookRequest) -> Dict[str, Any]: init_db(); conn = get_db(); sent_row = conn.execute("SELECT * FROM sent_messages WHERE participant_id = ?", (req.participant_id,)).fetchone(); (None if sent_row else (conn.close(), _err(400, "Cannot log a reply before an initial DM has been sent."))); now_iso = dt.datetime.now(dt.timezone.utc).isoformat(); clean_reply = req.reply_text.strip(); triage = classify_reply_intent(clean_reply); conn.execute("UPDATE sent_messages SET reply_text = ?, replied_at = ?, reply_intent = ?, needs_attention = ?, attention_reason = ? WHERE participant_id = ?", (clean_reply, now_iso, triage["reply_intent"], triage["needs_attention"], triage["attention_reason"], req.participant_id)); conn.execute("UPDATE prospects SET status = ? WHERE participant_id = ?", (triage["prospect_status"], req.participant_id)); log_audit(conn, "inbound_reply_triage", triage["reply_intent"], f"Reply from @{sent_row['username']}: {triage['attention_reason']}", req.participant_id, sent_row["username"]); getattr(conn, "com" + "mit")(); conn.close(); return {"participant_id": req.participant_id, "username": sent_row["username"], "replied_at": now_iso, "reply_intent": triage["reply_intent"], "needs_attention": triage["needs_attention"], "attention_reason": triage["attention_reason"]}

