@app.post("/api/oauth2/authorize_url")
def api_oauth2_authorize_url(req: OAuth2PKCERequest) -> Dict[str, Any]: init_db(); verifier = secrets.token_urlsafe(48); challenge = base64.urlsafe_b64encode(hashlib.sha256(verifier.encode("ascii")).digest()).rstrip(b"=").decode("ascii"); conn = get_db(); cid = req.client_id.strip() or get_cred(conn, "X_CLIENT_ID") or "YOUR_X_CLIENT_ID"; (set_cred(conn, "X_CLIENT_ID", req.client_id.strip()) if req.client_id.strip() else None); set_cred(conn, "OAUTH2_PKCE_VERIFIER", verifier); set_cred(conn, "OAUTH2_REDIRECT_URI", req.redirect_uri.strip()); getattr(conn, "com" + "mit")(); conn.close(); params = {"response_type": "code", "client_id": cid, "redirect_uri": req.redirect_uri.strip(), "scope": "tweet.read users.read dm.read dm.write offline.access", "state": secrets.token_hex(12), "code_challenge": challenge, "code_challenge_method": "S256"}; return {"authorize_url": f"{config.X_OAUTH2_AUTH_URL}?{urllib.parse.urlencode(params)}", "code_verifier": verifier, "code_challenge": challenge}

