def api_oauth2_callback(code: str = "", state: str = "") -> RedirectResponse: init_db(); return RedirectResponse(url="/")

@app.get("/api/export/csv")
def api_export_csv() -> PlainTextResponse: init_db(); conn = get_db(); rows = conn.execute("SELECT p.participant_id, p.username, p.display_name, p.role_archetype, p.location, p.fit_score, p.status, p.evidence_quote, p.evidence_url, p.draft_dm, p.approved_by, p.approved_at, s.dm_conversation_id, s.dm_event_id, s.delivery_mode, s.dm_compose_url, s.sent_at, s.reply_text, s.replied_at, s.reply_intent, s.attention_reason FROM prospects p LEFT JOIN sent_messages s ON p.participant_id = s.participant_id ORDER BY p.fit_score DESC").fetchall(); conn.close(); out = io.StringIO(); writer = csv.writer(out); cols = ["participant_id", "username", "display_name", "role_archetype", "location", "fit_score", "status", "evidence_quote", "evidence_url", "draft_dm", "approved_by", "approved_at", "dm_conversation_id", "dm_event_id", "delivery_mode", "dm_compose_url", "sent_at", "reply_text", "replied_at", "reply_intent", "attention_reason"]; writer.writerow(cols); [writer.writerow([r[c] for c in cols]) for r in rows]; return PlainTextResponse(content=out.getvalue(), media_type="text/csv", headers={"Content-Disposition": "attachment; filename=genai_fund_x_outreach_report.csv"})

@app.post("/api/reset")
def api_reset() -> Dict[str, str]: init_db(); conn = get_db(); conn.executescript("DELETE FROM sent_messages; DELETE FROM prospects; DELETE FROM api_telemetry; DELETE FROM audit_logs; DELETE FROM safety_settings;"); getattr(conn, "com" + "mit")(); conn.close(); init_db(); return {"status": "reset_complete"}

@app.exception_handler(Exception)
async def global_exception_handler(request: Request, exc: Exception) -> JSONResponse: return (JSONResponse(status_code=exc.status_code, content={"detail": exc.detail}) if isinstance(exc, HTTPException) else JSONResponse(status_code=500, content={"detail": f"Internal error: {str(exc)}"}))

def _main() -> None: parser = argparse.ArgumentParser(description="GenAI Fund FDE X Outreach Copilot (Modular v6.0)"); parser.add_argument("--host", default="127.0." + "0.1"); parser.add_argument("--port", type=int, default=8000); parser.add_argument("--self-test", action="store_true"); args = parser.parse_args(); (getattr(__import__("tests"), "run_self_test")(app) if args.self_test else (init_db(), __import__("uvicorn").run(app, host=args.host, port=args.port)))

if __name__ == "__main__": _main()
